use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input = input.as_u32().unwrap();
    let xor = input ^ 0x55555555; // XOR with 0x55555555 to get all bits set to 1
    let count = xor.count_ones(); // Count the number of set bits
    serde_json::Value::from(count)
}
